import {filterCards, makeRun, structureFor} from './logic.js';
const app=document.querySelector('#app');
const state={models:[],model:null,mode:'all',order:'sequential',tags:[],match:'all',run:null,index:0,revealed:false,complete:false,query:''};
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,cls='secondary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const segments=(values,current,action)=>`<div class="segments">${values.map(([value,label])=>button(label,action,'',`data-value="${value}" aria-pressed="${current===value}"`)).join('')}</div>`;
const selected=()=>state.model?filterCards(state.model.cards,state.mode,state.tags,state.match):[];
function library(){return `<aside class="library" aria-label="Models"><h2>Your models <span style="color:var(--muted);font-weight:400">/ ${state.models.length}</span></h2><input id="model-search" type="search" aria-label="Find a model" placeholder="Find a model…" value="${escape(state.query)}"><div class="model-list">${modelList()}</div></aside>`;}
function modelList(){const models=state.models.filter(m=>m.name.toLowerCase().includes(state.query.toLowerCase()));return models.length?models.map(m=>`<button class="model" data-action="model" data-value="${m.id}" aria-pressed="${m.id===state.model?.id}"><strong>${escape(m.name)}</strong><small>${m.count} cards · ${m.identificationCount} identification</small></button>`).join(''):'<p class="empty">No matching models.</p>';}
function setup(){const m=state.model;if(!m)return '<p class="loading" role="status">Loading model…</p>';const meta=state.models.find(x=>x.id===m.id);return `<section class="workspace"><div class="eyebrow">Choose your revision</div><h1 class="model-title">${escape(m.name)}</h1><div class="stats"><span><b>${m.cards.length}</b> cards</span><span><b>${meta.identificationCount}</b> identification</span></div><div class="panel options"><div><span class="option-label">Card set</span>${segments([['all','All cards'],['identification','Identification only']],state.mode,'mode')}</div><div><span class="option-label">Order</span>${segments([['sequential','In order'],['random','Random']],state.order,'order')}</div></div><section class="panel"><div class="filter-head"><h2>Filter by tag</h2>${button('Clear filters','clear','text-button',state.tags.length?'':'disabled')}</div><p class="filter-help">${state.tags.length?`${state.tags.length} selected`:'All tags included'} · Select tags to narrow your run.</p><div style="max-width:330px;margin-bottom:18px">${segments([['all','Match all selected'],['any','Match any selected']],state.match,'match')}</div><div class="chips">${meta.tags.map(t=>{const n=filterCards(m.cards,state.mode,[t],'all').length;return button(`#${escape(t)}<span>${n}</span>`,'tag','chip',`data-value="${escape(t)}" aria-pressed="${state.tags.includes(t)}"`)}).join('')}</div></section><div class="start-row"><div><strong>${selected().length} cards in this run</strong><p>${selected().length?'Every selected card, once. No scores or saved progress.':'No cards match. Try fewer tags or Match any selected.'}</p></div>${button('Start revision →','start','primary',selected().length?'':'disabled')}</div></section>`;}
function session(){if(state.complete)return `<section class="session"><div class="panel complete"><div class="complete-mark" aria-hidden="true">✓</div><div class="eyebrow">Run complete</div><h1>Every card covered.</h1><p>You reached the end of ${state.run.length} cards in<br>${escape(state.model.name)}.</p><div style="display:flex;flex-wrap:wrap;gap:12px;justify-content:center">${button('Start a fresh run','start','primary')}${button('Choose cards','exit')}</div></div></section>`;
const c=state.run[state.index];const identification=c.tags.includes('Identification');const structure=identification?'':structureFor(c,state.model.cards);return `<section class="session"><div class="session-top">${button('← Models & filters','exit','text-button')}<h1>${escape(state.model.name)}</h1><span class="session-count">${state.index+1} / ${state.run.length}</span></div><progress value="${state.index}" max="${state.run.length}" aria-label="Cards passed"></progress><article class="flashcard" tabindex="-1"><div class="card-meta"><span>${escape(c.section||'Model structures')}</span><span>${escape(c.question)}</span></div><div class="label-number">${escape(c.label||c.path.at(-1)||'—')}</div>${structure?`<div class="structure">${escape(structure)}</div>`:''}<h2 class="question">${identification?'Identify this structure':escape(c.question)}</h2>${state.revealed?`<div class="answer" role="status">${escape(c.answer)}</div>`:button('Reveal answer','reveal','primary reveal')}</article><div class="session-controls">${button('← Previous','previous','secondary',state.index?'':'disabled')}${button(state.index===state.run.length-1?'Finish run ✓':'Next card →','next','primary',state.revealed?'':'disabled')}</div><p class="shortcuts">Space to reveal · ← previous · → next after revealing</p></section>`;}
function render(){app.innerHTML=state.run?session():`<div class="layout">${library()}${setup()}</div>`;}
let loadVersion=0;
async function choose(id){const version=++loadVersion;state.run=null;state.model=null;state.tags=[];render();try{const meta=state.models.find(m=>m.id===id);if(!meta)throw Error('Unknown model');const response=await fetch('./data/'+meta.file);if(!response.ok)throw Error('Could not load model');const model=await response.json();if(version!==loadVersion)return;state.model=model;render();}catch(e){if(version===loadVersion)app.innerHTML=`<div class="error" role="alert">The model could not be loaded. ${button('Retry','retry')}</div>`;}}
function action(name,value){if(name==='model'){choose(value);return;}if(name==='retry'){choose(state.models[0].id);return;}if(name==='mode')state.mode=value;if(name==='order')state.order=value;if(name==='match')state.match=value;if(name==='tag')state.tags=state.tags.includes(value)?state.tags.filter(t=>t!==value):[...state.tags,value];if(name==='clear')state.tags=[];if(name==='start'){const cards=selected();if(!cards.length)return;state.run=makeRun(cards,state.order==='random');state.index=0;state.revealed=false;state.complete=false;window.scrollTo(0,0);}if(name==='exit'){state.run=null;state.complete=false;}if(name==='reveal')state.revealed=true;if(name==='previous'&&state.index>0){state.index--;state.revealed=false;}if(name==='next'&&state.revealed){if(state.index===state.run.length-1)state.complete=true;else{state.index++;state.revealed=false;}}render();if(state.run&&!state.complete)app.querySelector('.flashcard')?.focus({preventScroll:true});}
app.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(b&&!b.disabled)action(b.dataset.action,b.dataset.value);});
app.addEventListener('input',e=>{if(e.target.id==='model-search'){state.query=e.target.value;app.querySelector('.model-list').innerHTML=modelList();}});
document.addEventListener('keydown',e=>{if(!state.run||state.complete||e.altKey||e.ctrlKey||e.metaKey||/INPUT|SELECT|TEXTAREA|BUTTON|A/.test(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();if(!state.revealed)action('reveal');}if(e.key==='ArrowRight'){e.preventDefault();action('next');}if(e.key==='ArrowLeft'){e.preventDefault();action('previous');}});
try{const response=await fetch('./data/models.json');if(!response.ok)throw Error('Library unavailable');state.models=await response.json();if(!state.models.length)throw Error('No models available');await choose(state.models[0].id);}catch(e){app.innerHTML='<div class="error" role="alert"><h1>Unable to load the library</h1><p>Check that the data files are available, then reload this page.</p><button class="secondary" onclick="location.reload()">Reload</button></div>';}
if(document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'get_revision_selection',description:'Read the selected anatomy model, filters and current run position.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({model:state.model?.name,tags:state.tags,mode:state.mode,order:state.order,count:selected().length,position:state.run?state.index+1:null,complete:state.complete})});}catch{ /* Optional browser API. */ }}
